const express = require("express");
const app = express();

app.use(express.json());               // parse JSON bodies (default limit 100kb)

let todos = [];

app.get("/todos", (req, res) => res.json(todos));

app.post("/todos", async (req, res, next) => {
  try {
    const { title } = req.body;
    if (!title) return res.status(400).json({ error: "title required" });
    const todo = { id: todos.length + 1, title, done: false };
    todos.push(todo);
    res.status(201).json(todo);
  } catch (err) { next(err); }     // pass to error handler
});

// Error handler (last middleware, 4 args)
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: "internal" });
});

app.listen(3000);

const { Pool } = require("pg");

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,                    // max connections
  idleTimeoutMillis: 30_000,
  connectionTimeoutMillis: 2_000,
});

async function getUsers(limit = 100) {
  // Parameterized query — SAFE from SQL injection
  const { rows } = await pool.query(
    "SELECT id, name, email FROM users ORDER BY id LIMIT $1",
    [limit]
  );
  return rows;
}

async function getUserById(id) {
  const { rows } = await pool.query(
    "SELECT * FROM users WHERE id = $1",
    [id]
  );
  return rows[0] ?? null;
}

